use xiom.io;

type Ledger = {
  entries: Vec[Int];
  invariant: entries.len() >= 0;
}

fn inspect_all(ledger: &Ledger) -> Int {
  let total = 0;
  for entry in ledger.entries {
    total = total + entry;
  }
  return total;
}

fn add_entry(ledger: &mut Ledger, amount: Int)
  requires: amount > 0;
{
  ledger.entries.push(amount);
}

fn clear_ledger(ledger: &mut Ledger) {
  ledger.entries = Vec::new();
  ledger.entries.push(0);
}

fn main() -> Int {
  var l: Ledger = Ledger{ entries: Vec::new() };
  add_entry(&mut l, 100);
  add_entry(&mut l, 200);
  add_entry(&mut l, 300);
  let total = inspect_all(&l);
  clear_ledger(&mut l);
  let after = inspect_all(&l);
  return after;
}
